DROP TRIGGER IF EXISTS on_auth_user_created ON auth.users; DROP FUNCTION IF EXISTS public.handle_new_user(); DROP POLICY IF EXISTS "own profile" ON public.profiles; ALTER TABLE public.profiles DROP CONSTRAINT IF EXISTS profiles_id_fkey; ALTER TABLE public.profiles ALTER COLUMN id TYPE TEXT USING id::text; ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS email TEXT; CREATE POLICY "own profile" ON public.profiles FOR ALL USING ((auth.jwt() ->> 'sub') = id) WITH CHECK ((auth.jwt() ->> 'sub') = id); DROP POLICY IF EXISTS "own messages" ON public.chat_messages; ALTER TABLE public.chat_messages DROP CONSTRAINT IF EXISTS chat_messages_user_id_fkey; ALTER TABLE public.chat_messages ALTER COLUMN user_id TYPE TEXT USING user_id::text; CREATE POLICY "own messages" ON public.chat_messages FOR ALL USING ((auth.jwt() ->> 'sub') = user_id) WITH CHECK ((auth.jwt() ->> 'sub') = user_id); DROP POLICY IF EXISTS "own analyses" ON public.symptom_analyses; ALTER TABLE public.symptom_analyses DROP CONSTRAINT IF EXISTS symptom_analyses_user_id_fkey; ALTER TABLE public.symptom_analyses ALTER COLUMN user_id TYPE TEXT USING user_id::text; CREATE POLICY "own analyses" ON public.symptom_analyses FOR ALL USING ((auth.jwt() ->> 'sub') = user_id) WITH CHECK ((auth.jwt() ->> 'sub') = user_id); DROP POLICY IF EXISTS "own documents" ON public.documents; ALTER TABLE public.documents DROP CONSTRAINT IF EXISTS documents_user_id_fkey; ALTER TABLE public.documents ALTER COLUMN user_id TYPE TEXT USING user_id::text; CREATE POLICY "own documents" ON public.documents FOR ALL USING ((auth.jwt() ->> 'sub') = user_id) WITH CHECK ((auth.jwt() ->> 'sub') = user_id); ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS email_reminders_enabled BOOLEAN NOT NULL DEFAULT true; CREATE TABLE IF NOT EXISTS public.assistant_messages ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id TEXT NOT NULL, role TEXT NOT NULL CHECK (role IN ('user', 'assistant')), content TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now() ); GRANT SELECT, INSERT, UPDATE, DELETE ON public.assistant_messages TO authenticated; GRANT ALL ON public.assistant_messages TO service_role; ALTER TABLE public.assistant_messages ENABLE ROW LEVEL SECURITY; DROP POLICY IF EXISTS "own assistant messages" ON public.assistant_messages; CREATE POLICY "own assistant messages" ON public.assistant_messages FOR ALL USING ((auth.jwt() ->> 'sub') = user_id) WITH CHECK ((auth.jwt() ->> 'sub') = user_id); CREATE INDEX IF NOT EXISTS assistant_messages_user_idx ON public.assistant_messages(user_id, created_at);